"""
    Print wrapped sequence.

    Args:
        seq (str): Nucleotide sequence
        bases (int): Number of bases to include on each line.
    """
def wrap(seq: Any, bases: Any = 60) -> object {
    count = 0;
    ret = '';
    for i in seq {
        if (count >= bases) {
            ret = ret + '\n';
            count = 0;
        }
        ret = ret + i;
        count += 1;
    }
    return ret;
}

"""
    Method decorator to indicate that a method definition shall
    silently be ignored if it already exists in the target class.
    """
def no_replace(f: Any) -> object {
    f.__no_replace = True;
    return f;
}

"""remotes the host and path from a URI, returning only the final resource name
    """
def strip_uri_host_and_path(concept_uri: Any) -> object {
    if (concept_uri is None) {
        return None;
    }
    rightmost_slash_position = concept_uri.rfind('/');
    rightmost_colon_position = concept_uri.rfind(':');
    simplified_start = max(
        0, (rightmost_slash_position + 1), (rightmost_colon_position + 1)
    );
    return concept_uri[simplified_start:];
}

