"""calculate the angular radius for a given distance in kilometers"""
def calc_angular_radius(km: Any) -> object {
    earth_radius = 6371.0;
    return (km / earth_radius);
}

"""
    Takes a number and returns a string putting a zero in front if it's
    single digit.
    """
def stringify(num: Any) -> object {
    num_string = str(num);
    if (len(num_string) == 1) {
        num_string = '0' + num_string;
    }
    return num_string;
}
